window.ScripturaLexicons.BDAG_PART_0317 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0317-01\" data-source=\"BDAG\" data-search=\"ῥυπαρία, ας, ἡ substantivo feminino impureza moral, vileza, avareza BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ῥυπαρία, ας, ἡ</td><td>substantivo feminino</td><td>impureza moral, vileza, avareza</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0317-02\" data-source=\"BDAG\" data-search=\"ῥυπαρός, ά, όν adjetivo sujo, imundo; moralmente impuro BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ῥυπαρός, ά, όν</td><td>adjetivo</td><td>sujo, imundo; moralmente impuro</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0317-03\" data-source=\"BDAG\" data-search=\"ῥύπος, ου, ὁ substantivo masculino sujeira; impureza; sumo viscoso BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ῥύπος, ου, ὁ</td><td>substantivo masculino</td><td>sujeira; impureza; sumo viscoso</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0317-04\" data-source=\"BDAG\" data-search=\"ῥυπόω verbo macular, contaminar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ῥυπόω</td><td>verbo</td><td>macular, contaminar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0317-05\" data-source=\"BDAG\" data-search=\"ῥύσις, εως, ἡ substantivo feminino fluxo, escoamento BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ῥύσις, εως, ἡ</td><td>substantivo feminino</td><td>fluxo, escoamento</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0317-06\" data-source=\"BDAG\" data-search=\"ῥυτίς, ίδος, ἡ substantivo feminino ruga BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ῥυτίς, ίδος, ἡ</td><td>substantivo feminino</td><td>ruga</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0317-07\" data-source=\"BDAG\" data-search=\"Ῥωμαϊκός, ή, όν adjetivo romano, latino BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ῥωμαϊκός, ή, όν</td><td>adjetivo</td><td>romano, latino</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0317-08\" data-source=\"BDAG\" data-search=\"Ῥωμαῖος, α, ον adjetivo; substantivo romano, cidadão romano BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ῥωμαῖος, α, ον</td><td>adjetivo; substantivo</td><td>romano, cidadão romano</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0317-09\" data-source=\"BDAG\" data-search=\"Ῥωμαϊστί advérbio em latim BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ῥωμαϊστί</td><td>advérbio</td><td>em latim</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0317-10\" data-source=\"BDAG\" data-search=\"Ῥώμη, ης, ἡ nome próprio feminino Roma BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ῥώμη, ης, ἡ</td><td>nome próprio feminino</td><td>Roma</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0317-11\" data-source=\"BDAG\" data-search=\"ῥώννυμι verbo fortalecer; passar bem, adeus BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ῥώννυμι</td><td>verbo</td><td>fortalecer; passar bem, adeus</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0317-12\" data-source=\"BDAG\" data-search=\"σαβαχθάνι forma verbal aramaica transliterada abandonaste-me BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σαβαχθάνι</td><td>forma verbal aramaica transliterada</td><td>abandonaste-me</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0317-13\" data-source=\"BDAG\" data-search=\"Σαβαώθ termo hebraico indeclinável Sabaote, exércitos BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Σαβαώθ</td><td>termo hebraico indeclinável</td><td>Sabaote, exércitos</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0317-14\" data-source=\"BDAG\" data-search=\"σαββατίζω verbo guardar o sábado BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σαββατίζω</td><td>verbo</td><td>guardar o sábado</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0317-15\" data-source=\"BDAG\" data-search=\"σαββατισμός, οῦ, ὁ substantivo masculino descanso sabático, observância do sábado BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σαββατισμός, οῦ, ὁ</td><td>substantivo masculino</td><td>descanso sabático, observância do sábado</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0317-16\" data-source=\"BDAG\" data-search=\"σάββατον, ου, τό substantivo neutro sábado; semana BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σάββατον, ου, τό</td><td>substantivo neutro</td><td>sábado; semana</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0317-17\" data-source=\"BDAG\" data-search=\"σαγήνη, ης, ἡ substantivo feminino rede de arrasto BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σαγήνη, ης, ἡ</td><td>substantivo feminino</td><td>rede de arrasto</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0317-18\" data-source=\"BDAG\" data-search=\"Σαδδουκαῖος, ου, ὁ substantivo masculino saduceu BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Σαδδουκαῖος, ου, ὁ</td><td>substantivo masculino</td><td>saduceu</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0317-19\" data-source=\"BDAG\" data-search=\"Σαδώκ, ὁ nome próprio masculino indeclinável Zadoque BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Σαδώκ, ὁ</td><td>nome próprio masculino indeclinável</td><td>Zadoque</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0317-20\" data-source=\"BDAG\" data-search=\"σαίνω verbo adular, lisonjear; perturbar, agitar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σαίνω</td><td>verbo</td><td>adular, lisonjear; perturbar, agitar</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0317-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥυπαρία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ῥυπαρία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (desde Critias [V a.C.] em Pollux 3, 116) prim. ‘sujeira, imundície’, fig., sob o aspecto ético, estado de contaminação ou corrupção moral, impureza moral, vileza (Pel.-Leg. p. 6, 30 <span class=\"greek\">ἀφῆκεν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ὕδατι</span> <span class=\"greek\">πᾶσαν</span> <span class=\"greek\">αὐτῆς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ῥυπαρίαν</span>; Did., Gen. 89, 9 <span class=\"greek\">ἡ</span> <span class=\"greek\">ῥ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">ἁμαρτίας</span>), esp. avareza sórdida, cobiça (Teles p. 33, 4; 37, 5 H.; Plut., Mor. 60d; Cass. Dio 74, 5, 7; TestSol 10:12 C) com <span class=\"greek\">κακία</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.21\" target=\"_blank\" rel=\"noopener noreferrer\">Js 1:21</a>.—DELG s.v. <span class=\"greek\">ῥύπος</span>. M-M. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0317-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥυπαρός, ά, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ῥυπαρός</span>, <span class=\"greek\">ά</span>, <span class=\"greek\">όν</span> (<span class=\"greek\">ῥύπος</span>; Teleclides Com. [V a.C.], Fgm. 3; Hippocr. et al.; pap., LXX; Just., D. 116, 1)</p><p class=\"entry-text\">① relativo ao estado de estar sujo, imundo, maculado, um lugar sujo Hs 9, 7, 6; vestes imundas (Plut., Phoc. 750 [18, 4]; Cass. Dio 65, 20; Artem. 2, 3 p. 88, 23; Aelian, VH 14, 10; PGiss 76, 2f [II d.C.]; Zech 3:3f; SibOr 5, 188; Jos., Ant. 7, 267 <span class=\"greek\">ῥυπαρὰν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἐσθῆτα</span>) <span class=\"greek\">ἐσθής</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">Js 2:2</a>. <span class=\"greek\">ῥάκη</span> <span class=\"greek\">ῥ</span>. trapos imundos (v. <span class=\"greek\">ῥάκος</span> 1) ApcPt 15, 30. Em linguagem figurada motivada pela proximidade de <span class=\"greek\">ῥύπος</span>: <span class=\"greek\">ἡμέραι</span> <span class=\"greek\">ῥ</span>. dias impuros B 8:6.</p><p class=\"entry-text\">② relativo à sordidez moral, impuro, contaminado, extensão fig. de 1 (Dionys. Hal. et al. empregam a palavra no sentido de ‘sordidamente avarento’; v. Vett. Val. 104, 5; 117, 10; Test Jud 14:3 <span class=\"greek\">διαλογισμοὶ</span> <span class=\"greek\">ῥ</span>.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.22.11\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 22:11</a>; IEph 16:2 (cf. <span class=\"greek\">ἐν</span> … <span class=\"greek\">πάσῃ</span> <span class=\"greek\">ῥυπαρᾷ</span> <span class=\"greek\">πράξει</span> Just., D. 116, 1).—B. 1081.—DELG s.v. <span class=\"greek\">ῥύπος</span>. M-M. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0317-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥύπος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ῥύπος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (Hom. et al.; LXX) prim. ‘uma substância imunda, sujeira’</p><p class=\"entry-text\">① sujidade como matéria residual, distinta da terra, sujeira (Hom. et al.) <span class=\"greek\">σαρκὸς</span> <span class=\"greek\">ἀπόθεσις</span> <span class=\"greek\">ῥύπου</span> remoção da sujeira do corpo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.21\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 3:21</a> (sobre o gen. v. W-S. §30, 12f; sobre o assunto cf. FSokolowski, Lois sacrées des cités grecques, Suppl. ’62, n. 108, 4–7).</p><p class=\"entry-text\">② extensão fig. de 1 (M. Ant. 7, 47 <span class=\"greek\">ὁ</span> <span class=\"greek\">ῥύπος</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">χαμαὶ</span> <span class=\"greek\">βίου</span>; Is 4:4), em sentido ético, impureza <span class=\"greek\">καθαρὸς</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">ῥύπου</span> 1 Cl 17:4 (Job 14:4; a passagem de Job também em Philo, Mut. Nom. 48). Com <span class=\"greek\">ἀμαρτίαι</span> B 11:11.</p><p class=\"entry-text\">③ um sumo escuro e viscoso, sumo (para <span class=\"greek\">ῥ</span>. no sentido de uma secreção, p. ex. cerume, v. Aristot., Fgm. 289 p. 226, 1 Rose; Artem. 1, 24; PGM 36, 332) <span class=\"greek\">ῥ</span>. <span class=\"greek\">ὑσσώπου</span> sumo escuro do hissopo, talvez no sentido de ‘sumo imundo do hissopo’ B 8:6 (mas JKleist, trad. ’48, p. 175 nota 97, relaciona-o à mistura de água e cinzas da novilha, aspergida por meio do hissopo).—DELG. M-M. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0317-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥυπόω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ῥυπόω</span> (<span class=\"greek\">ῥύπος</span>) 1 aor. imper. 3ª pess. sing. <span class=\"greek\">ῥυπωσάτω</span> (Od. 6, 59; escól. sobre Apollon. Rhod. 2, 301–2a; Themist., Or. 7 p. 112, 6; Achmes 63, 8; 118, 2; Pel.-Leg. 9, 9; Pollux 4, 180; Philo, Fgm. 9 RHarris) extensão fig. do sentido prim. ‘tornar sujo, sujar’: macular, contaminar <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.22.11\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 22:11</a> t.r. (leitura erasmiana; v. <span class=\"greek\">ῥυπαίνω</span>, <span class=\"greek\">ῥυπαρεύω</span>).—DELG s.v. <span class=\"greek\">ῥύπος</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0317-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥύσις, εως, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ῥύσις</span>, <span class=\"greek\">εως</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">ῥέω</span>; Hippocr., Pla. et al.; pap.; En 26:2; Philo; SibOr 1, 315) escoamento, fluxo <span class=\"greek\">ῥ</span>. <span class=\"greek\">αἵματος</span> fluxo de sangue (Lev 15:25; escritos médicos [Hobart 15]; Diod S 5, 31, 3; Aelian, VH 6, 6 p. 79, 17; Vett. Val. 282, 30 <span class=\"greek\">αἵματος</span> <span class=\"greek\">πολλὴν</span> <span class=\"greek\">ῥύσιν</span>), a respeito de uma hemorragia de que sofria uma mulher <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:25</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.43\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:43</a>f (Acta Pilati 7=A Syn. 95, 91).—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0317-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥυτίς, ίδος, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ῥυτίς</span>, <span class=\"greek\">ίδος</span>, <span class=\"greek\">ἡ</span> (Aristoph., Pla. et al.; Plut., Mor. 789d; Lucian) uma ruga, em linguagem figurada, a respeito da igreja <span class=\"greek\">μὴ</span> <span class=\"greek\">ἔχουσα</span> <span class=\"greek\">σπῖλον</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">ῥυτίδα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.27\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 5:27</a>.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0317-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ῥωμαϊκός, ή, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Ῥωμαϊκός</span>, <span class=\"greek\">ή</span>, <span class=\"greek\">όν</span> (Polyb. et al.; Arrian, Peripl. 10, 1 <span class=\"greek\">τὰ</span> <span class=\"greek\">Ῥωμαϊκὰ</span> <span class=\"greek\">γράμματα</span>=a letra latina; inscr., pap., Philo, Joseph.; Just., A I, 26, 2) romano, latino <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.38\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 23:38</a> v.l.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0317-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ῥωμαῖος, α, ον</h1><div class=\"entry-meta\"><span>adjetivo; substantivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Ῥωμαῖος</span>, <span class=\"greek\">α</span>, <span class=\"greek\">ον</span> relativo à cidade de Roma ou ao Império Romano, romano; subst. <span class=\"greek\">ὁ</span> <span class=\"greek\">Ῥ</span>. (Polyb.+) o romano, o cidadão romano, pl. os romanos como povo ou cidadãos romanos (Appian, Bell. Civ. 2, 26 §98 <span class=\"greek\">Ῥωμαίων</span> <span class=\"greek\">πολῖται</span> e <span class=\"greek\">Ῥωμαῖοι</span> alternam-se) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.48\" target=\"_blank\" rel=\"noopener noreferrer\">J 11:48</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:10</a>; 16:21, 37f; 22:25–27, 29; 23:27 (sobre a cidadania romana v. FSchulz, Rom. Registry of Births, JRS 32, ’42, 78–91; 33, ’43, 55–64 HTajra, The Trial of St Paul ’89, 81–89); 25:16; 28:17 (sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.37\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 16:37</a>f; 22:25 v. <span class=\"greek\">μαστίζω</span>). Phlm subscr. No sentido de cristãos romanos, Ro ins. <span class=\"greek\">χωρίον</span> <span class=\"greek\">Ῥωμαίων</span> IRo ins (v. Hdb. ad loc.). <span class=\"greek\">ἡ</span> <span class=\"greek\">Ῥωμαίων</span> <span class=\"greek\">πόλις</span> Roma (Jos., C. Ap. 1, 66, Ant. 19, 7) EpilMosq 4. <span class=\"greek\">ἡ</span> <span class=\"greek\">Ῥωμαίων</span> <span class=\"greek\">ἡγεμωνία</span> o Império Romano AcPl Ha 9, 3 (cf. <span class=\"greek\">τὸ</span> <span class=\"greek\">Ῥωμαίων</span> <span class=\"greek\">κράτος</span>).—RAC II, 779–86; BHHW III 1610f; EDNT.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0317-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ῥωμαϊστί</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Ῥωμαϊστί</span> adv. na língua latina, em latim (Diosc. I 115, 5; Epict. 1, 17, 16; Jos., Ant. 14, 191 <span class=\"greek\">ἑλληνιστὶ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ῥωμαϊστί</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.20\" target=\"_blank\" rel=\"noopener noreferrer\">J 19:20</a>.—Subscr. após Mk no minúsculo 13 et al. (o grupo Ferrar. K e SLake, Studies and Documents XI ’41, 116) <span class=\"greek\">ἐγράφη</span> <span class=\"greek\">ῥωμαϊστὶ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">Ῥώμῃ</span>.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0317-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ῥώμη, ης, ἡ</h1><div class=\"entry-meta\"><span>nome próprio feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Ῥώμη</span>, <span class=\"greek\">ης</span>, <span class=\"greek\">ἡ</span> (Aristot., Polyb. et al.; inscr., 1 Macc, SibOr, Philo, Joseph., Just.) a capital do Império Romano, Roma sem art. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 19:21</a>; 23:11; 28:16; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:7</a> (onde as palavras <span class=\"greek\">ἐν</span> <span class=\"greek\">Ῥ</span>. faltam em muitos mss.; v. Ltzm., Hdb. exc. sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:7</a>; Zahn, comm., exc. I p. 615; Harnack, ZNW 3, 1902, 83ff; RSteinmetz, ZNW 9, 1908, 177ff), v. 15 (aqui também as palavras <span class=\"greek\">ἐν</span> <span class=\"greek\">Ῥώμῃ</span> são omitidas em alguns mss. isolados); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.1.17\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 1:17</a>; 1 Cl ins; IEph 1:2; 21:2; IRo 5:1; 10:2; EpilMosq 2; Hv 1, 1, 1. Também <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.5.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 5:13</a> v.l. e a subscr. de Gal, Eph, Phil, Col, 2 Th, 2 Ti, Phlm, Hb; AcPl Ha 7, 8 e 14.—Com art. (Just., A I, 56, 2 <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">βασιλίδι</span> <span class=\"greek\">Ῥώμῃ</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.18.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 18:2</a>; 28:14, 16 v.l.; AcPl Ha 6, 16; 7, 8 e 32; 9, 19. V. verbete anterior.—Pauly-W. IV 1441–51; Kl. Pauly IV 1441ff; BHHW III 1606–9; EDNT.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0317-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥώννυμι</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ῥώννυμι</span> na voz ativa (obsoleta na época do NT) ‘fortalecer’; o perf. pass. (no sentido de ‘ser forte’, desde Eur., Thu.; também LXX.—Tat. 32, 3; Ath. 27, 1 [ambos <span class=\"greek\">ἐρρωμένος</span>]) <span class=\"greek\">ἔρρωμαι</span>, inf. <span class=\"greek\">ἐρρῶσθαι</span>, imper. <span class=\"greek\">ἔρρωσο</span>, <span class=\"greek\">ἔρρωσθε</span> (sempre com <span class=\"greek\">ρ</span> duplo: B-D-F §11, 1; Mlt-H. 101f). As cartas greco-romanas geralmente incluíam no início perguntas acerca da saúde do destinatário e, ao final, um desejo de bem-estar para ele. A última fórmula era freq. expressa com o verbo <span class=\"greek\">ῥ</span>. no imper. perf. pass.: estar de boa saúde, passar bem, adeus (Hippocr., X., Pla.+; inscr. [SIG 4 p. 549b índice]; pap. [muito freq.; v. FExler, The Form of the Ancient Gk. Letter 1923, 74ff; HLietzmann, Kl. Texte 14, 2 1910, n. 3; 4; 6; 7; 8 al.] 2 Macc 11:21, 33; 3 Macc 7:9; TestSol 22:5 B; EpArist 40; 46; Jos., Vi. 227; 365) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.29\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 15:29</a>; 23:30 v.l.; IEph 21:2; IMg 15; ITr 13:2; IRo 10:3; IPhld 11:2; ISm 13:1f; IPol 8:3b (em Ign. a saudação combina-se com vários acréscimos do uso cristão). <span class=\"greek\">ἔρρωσο</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">κυρίῳ</span> AcPlCor 1:16. Perifrasticamente <span class=\"greek\">ἐρρῶσθαι</span> <span class=\"greek\">ὑμᾶς</span> <span class=\"greek\">εὔχομαι</span> (freq. pap.) IPol 8:3a; MPol 22:1.—DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0317-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σαβαχθάνι</h1><div class=\"entry-meta\"><span>forma verbal aramaica transliterada</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σαβαχθάνι</span> (também <span class=\"greek\">σαβαχθανεί</span>; aram. <span class=\"hebrew\">שְׁבַקְתַּנִי</span> em vez do hebr. <span class=\"hebrew\">עֲזַבְתָּנִי</span> Ps 22:2; de <span class=\"hebrew\">שְׁבַק</span>) abandonaste-me <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.46\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:46</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:34</a>.—EKautzsch, Gramm. des Bibl.-Aram. 1884, 11; Dalman, Gramm.2 147 nota 4; 156; 221, Jesus 1922, 185f [trad. ingl. 204f]; DSidersky, RHR 103, ’31, 151–54. Sobre o acento v. Wlh. sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:34</a>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0317-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Σαβαώθ</h1><div class=\"entry-meta\"><span>termo hebraico indeclinável</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Σαβαώθ</span> indecl. Sabaote (LXX; TestSol; SibOr; Just., D. 64, 2; PGM 4, 1235; 15, 14; 18a, 1; 35, 20; IDefixWünsch 2; 3, 27; 4, 15) transcrição grega de <span class=\"hebrew\">צְבָאוֹת</span>, pl. de <span class=\"hebrew\">צָבָא</span>=exército, em um nome aplicado a Deus <span class=\"greek\">κύριος</span> <span class=\"greek\">Σ</span>.=<span class=\"hebrew\">יהוה</span> <span class=\"hebrew\">צְבָאוֹת</span> Yahweh, Senhor dos Exércitos, Senhor das Hostes (sobre o sentido EKautzsch, RE XXI 1908, 620–27 [lit.]; aqui 626f um breve tratamento do uso na LXX. Também XXIV 1913, 661f. Informações mais detalhadas em Thackeray 9; PKatz, Philo’s Bible, 146–49; BWambacq, L’épithète divine Jahwe Sebbâôt, ’47; BHHW III 2205; ZTalshir, JQR 78, ’87, 57–75 [LXX]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.29\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 9:29</a> (Is 1:9); 1 Cl 34:6 (Is 6:3); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.4\" target=\"_blank\" rel=\"noopener noreferrer\">Js 5:4</a>.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0317-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σαββατίζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σαββατίζω</span> fut. <span class=\"greek\">σαββατιῶ</span> LXX; 1 aor. <span class=\"greek\">ἐσαββάτισα</span>; perf. 3ª pess. sing. <span class=\"greek\">σεσαββάτικε</span> (Just., D. 12, 3) (LXX, Just.; crôn. biz. em Psaltes p. 329) guardar o sábado <span class=\"greek\">ἐὰν</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">σαββατίσητε</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">σάββατον</span>, <span class=\"greek\">οὐκ</span> <span class=\"greek\">ὄψεσθε</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">πατέρα</span> Ox 1, 8–10 (v. GTh 27; LWright, JBL 65, ’46, 180). Por outro lado, os judeus que se tornam cristãos abandonam a celebração do sábado em favor do dia do Senhor, o domingo IMg 9:1.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0317-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σαββατισμός, οῦ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σαββατισμός</span>, <span class=\"greek\">οῦ</span>, <span class=\"greek\">ὁ</span> (<span class=\"greek\">σαββατίζω</span>; Plut., Mor. 166a conj.; Just., D. 23, 3) descanso sabático, observância do sábado fig. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.4.9\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 4:9</a> um período especial de descanso para o povo de Deus, modelado segundo o sábado tradicional (CBarrett, CHDodd Festschr. ’56, 371f [escat.]).—V. sobre <span class=\"greek\">κατάπαυσις</span> HWeiss, CBQ 58, ’96, 674–89. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0317-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σάββατον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σάββατον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> (<span class=\"hebrew\">שַׁבָּת</span>) dat. pl. <span class=\"greek\">σάββασιν</span> (Meleager [I]: Anth. Pal. 5, 160; 1 Macc 2:38; Jos., Vi. 279, Ant. 16, 163; Just., D. 27, 5; 29, 3) sempre no NT, exceto que uma v.l. em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:1</a> e 12 segundo o códice B apresenta <span class=\"greek\">σαββάτοις</span> (assim usualmente a LXX [Thackeray 35]; Jos., Bell. 1, 146, Ant. 3, 294. V. W-S. §8, 12; B-D-F §52; Mlt-H. 128; MBlack, BRigaux Festschr. ’70, 60f.—A palavra encontra-se em Plut. et al.; pap., LXX; En 10:17; Philo, Joseph.)</p><p class=\"entry-text\">① o sétimo dia da semana no calendário de Israel, caracterizado pelo descanso do trabalho e por cerimônias religiosas especiais, sábado</p><p class=\"entry-text\">ⓐ sing. (<span class=\"greek\">τὸ</span>) <span class=\"greek\">σάββατον</span> (Nepualius [I d.C.] ed. W Gemoll, Progr. Striegau 1884, 53; LXX; Philo, Cher. 87; Jos., Ant. 3, 143; 255; Just., D. 8, 4 al.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 2:27</a>f (Alex. Aphr., Eth. Probl. 10, II 2 p. 130, 34ff <span class=\"greek\">ὁ</span> <span class=\"greek\">ἄνθρωπος</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἀρετῶν</span> <span class=\"greek\">χάριν</span>, <span class=\"greek\">ἀλλ</span>’ <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἔμπαλιν</span> [=vice-versa]); 6:2; 15:42 v.l.; 16:1; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.5\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:5</a>; 23:54; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.9\" target=\"_blank\" rel=\"noopener noreferrer\">J 5:9</a>f; 9:14; B 15:1a, 3; GPt 2:5 al. <span class=\"greek\">ἁγιάζειν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ς</span>. B 15:1b (v. 2 Esdr 23:22). <span class=\"greek\">βεβηλοῦν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ς</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:5</a>b; <span class=\"greek\">λύειν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ς</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.18\" target=\"_blank\" rel=\"noopener noreferrer\">J 5:18</a> (v. <span class=\"greek\">λύω</span> 4). <span class=\"greek\">τηρεῖν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ς</span>. 9:16 (cf. Just., D. 10, 3). <span class=\"greek\">σαββατίζειν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ς</span>. (cf. Lev 23:32) Ox 1, 9f (GTh 27) <span class=\"greek\">φυλάσσειν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ς</span>. (v. Ex 31:13f; Lev 19:3; Just., D. 8, 4) B 15:2, v. vers. 3. No sábado (v. B-D-F §200, 3; Rob. 523): <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">σαββάτῳ</span> (2 Esdr 23:15a, 16) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.7\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.31\" target=\"_blank\" rel=\"noopener noreferrer\">J 19:31</a>a; <span class=\"greek\">ἐν</span> <span class=\"greek\">σαββάτῳ</span> (2 Esdr 20:32b) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.1\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.16\" target=\"_blank\" rel=\"noopener noreferrer\">J 5:16</a>; 7:22f; <span class=\"greek\">τῷ</span> <span class=\"greek\">σαββάτῳ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.4\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:4</a> D (Unknown Sayings, 49–54); 6:9; 13:14a, 15; 14:3; <span class=\"greek\">τῷ</span> <span class=\"greek\">σαββάτῳ</span> <span class=\"greek\">ἐπερχομένης</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">κυριακῆς</span> AcPl Ha 3, 8. <span class=\"greek\">σαββάτῳ</span> (Jos., Bell. 2, 456) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:20</a> (v. Boll 134, 1); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.14.1\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 14:1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.59\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:59</a> v.l.; <span class=\"greek\">ἐν</span> <span class=\"greek\">ἑτέρῳ</span> <span class=\"greek\">ς</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.6\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:6</a>; <span class=\"greek\">τῷ</span> <span class=\"greek\">ἐρχομένῳ</span> <span class=\"greek\">ς</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.44\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:44</a>; <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ἡμέρᾳ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ς</span>. (cf. Jer 17:21f) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.14.5\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 14:5</a> v.l.; <span class=\"greek\">ἐν</span> <span class=\"greek\">ἡμέρᾳ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ς</span>. (2 Esdr 20:32a; 23:15b; cf. Cyranides p. 79, 11 <span class=\"greek\">ἐν</span> <span class=\"greek\">ἡμ</span>. <span class=\"greek\">σαββάτου</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.14.5\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 14:5</a>; <span class=\"greek\">τῇ</span> <span class=\"greek\">ἡμέρᾳ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ς</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.14\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 13:14</a>b, 16. No acus. de duração temporal (B-D-F §161, 2) <span class=\"greek\">τὸ</span> <span class=\"greek\">σάββατον</span> durante todo o sábado <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.56\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 23:56</a>. <span class=\"greek\">κατὰ</span> <span class=\"greek\">πᾶν</span> <span class=\"greek\">ς</span>. (em) cada sábado <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.27\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:27</a>; 15:21; 18:4; <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">μεταξὺ</span> <span class=\"greek\">ς</span>. no sábado seguinte 13:42. <span class=\"greek\">ἡ</span> <span class=\"greek\">ἡμέρα</span> <span class=\"greek\">πρὸ</span> <span class=\"greek\">σαββάτου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.54\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 23:54</a> D.—<span class=\"greek\">σάββατον</span> <span class=\"greek\">μέγα</span> grande sábado MPol 8:1; 21:1; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.31\" target=\"_blank\" rel=\"noopener noreferrer\">J 19:31</a>b (v. ESchwartz, Christl. u. jüd. Ostertafeln: AGG VIII/6, 1905, 127). <span class=\"greek\">ς</span>. <span class=\"greek\">τὸ</span> <span class=\"greek\">λεγόμενον</span> <span class=\"greek\">πρῶτον</span> o chamado primeiro sábado PtK 2, p. 14, 28.—Sobre <span class=\"greek\">σαββάτου</span> <span class=\"greek\">ὁδός</span> distância de uma jornada sabática <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:12</a> v. <span class=\"greek\">ὁδός</span> 2.</p><p class=\"entry-text\">ⓑ pl.</p><p class=\"entry-text\"><span class=\"greek\">α</span>. a respeito de mais de um sábado (2 Ch 31:3; Ezk 46; 3; Jos., Ant. 13, 252; Just., D. 10, 3 al.) <span class=\"greek\">σάββατα</span> <span class=\"greek\">τρία</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 17:2</a>. B 15:8a (Is 1:13), b.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. <span class=\"greek\">τὰ</span> <span class=\"greek\">σάββατα</span> para um único dia de sábado (PCairZen 762, 6 [III a.C.]; Plut., Mor. 169c; 671e <span class=\"greek\">τὴν</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">σαββάτων</span> <span class=\"greek\">ἑορτήν</span>; 672a; Ex 20:10; Lev 23:32 al.; Philo, Abr. 28 <span class=\"greek\">τὴν</span> <span class=\"greek\">ἑβδόμην</span>, <span class=\"greek\">ἣν</span> <span class=\"greek\">Ἑβραῖοι</span> <span class=\"greek\">σάββατα</span> <span class=\"greek\">καλοῦσιν</span>; Jos., Ant. 1, 33; 3, 237; 12, 259; 276.—B-D-F §141, 3 ; Rob. 408; ESchwyzer, ZVS 62, ’35, 1–16; ASchlatter, Mt 1929, 393) <span class=\"greek\">ὀψὲ</span> <span class=\"greek\">σαββάτων</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.28.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 28:1</a>a (v. <span class=\"greek\">ὀψέ</span> 3). Também provavelmente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.16\" target=\"_blank\" rel=\"noopener noreferrer\">Col 2:16</a>. <span class=\"greek\">ἡ</span> <span class=\"greek\">ἡμέρα</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">σαββάτων</span> (Ex 20:8; 35:3; Dt 5:12; Jer 17:21f; Jos., Ant. 12, 274; Just., 27, 5) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.16\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:14</a>; 16:13; Dg 4:3. (<span class=\"greek\">ἐν</span>) <span class=\"greek\">τοῖς</span> <span class=\"greek\">σάββασιν</span> no sábado (Jos., Vi. 279 <span class=\"greek\">τοῖς</span> <span class=\"greek\">σάββασιν</span>, Ant. 13, 252 v.l. <span class=\"greek\">ἐν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">σάββασιν</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:1</a>, 5, 10–12; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:21</a>; 2:23, 24; 3:2, 4; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.31\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:31</a>; 6:2; 13:10. <span class=\"greek\">ἡ</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">σάββατα</span> <span class=\"greek\">δεισιδαιμονία</span> veneração fanática do sábado Dg 4:1 (somente perigo extremo para a vida humana pode ocasionar a suspensão da lei sabática: Synes., Ep. 4 p. 162bc). <span class=\"greek\">τὰ</span> <span class=\"greek\">σάββατα</span> as festas sabáticas B 2:5 (Is 1:13).—JMeinhold, Sabbat u. Woche im AT 1905, Sabbat u. Sonntag 1909; JHehn, Siebenzahl u. Sabbat bei den Babyloniern u. im AT 1907, Der israelit. Sabbat 1909, Zur Sabbatfrage: BZ 14, 1917, 198–213; EMahler, Der Sabbat: ZDMG 62, 1908, 33–79, Handbuch der jüd. Chronologie 1916; GBeer, Schabbath1908; WNowack, Schabbat 1924; MWolff, Het ordeel der helleensch-romeinsche schrijvers over … den Sabbath: TT 44, 1910, 162–72; ELohse, Jesu Worte über den Sabbat, Beih. ZNW 26, ’60, 79–89; Moore, Judaism v. índice; Schürer II 424–27; 447–54; 467–75. V. também <span class=\"greek\">κυριακός</span>, final.</p><p class=\"entry-text\">② um período de sete dias, semana</p><p class=\"entry-text\">ⓐ sing. <span class=\"greek\">δὶς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">σαββάτου</span> dois dias (em) uma semana <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.12\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 18:12</a>. <span class=\"greek\">πρώτῃ</span> <span class=\"greek\">σαββάτου</span> no primeiro dia da semana (domingo) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.16.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 16:9</a>. <span class=\"greek\">κατὰ</span> <span class=\"greek\">μίαν</span> <span class=\"greek\">σαββάτου</span> a cada domingo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.16.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 16:2</a>. <span class=\"greek\">πρωὶ̈</span> <span class=\"greek\">μιᾶς</span> <span class=\"greek\">σαββάτου</span> cedo na manhã de domingo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.16.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 16:2</a> D.</p><p class=\"entry-text\">ⓑ pl. (<span class=\"greek\">ἡ</span>) <span class=\"greek\">μία</span> (<span class=\"greek\">τῶν</span>) <span class=\"greek\">σαββάτων</span> (isto é, <span class=\"greek\">ἡμέρα</span>) o primeiro dia da semana <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.28.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 28:1</a>b (Just., D. 41, 4; v. Dalman, Gramm. 247; SKrauss, Talm. Archäologie II 1911, 428f; PGardner-Smith, JTS 27, 1926, 179–81); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.16.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 16:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.1\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 24:1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.20.1\" target=\"_blank\" rel=\"noopener noreferrer\">J 20:1</a>, 19; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 20:7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.16.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 16:2</a> v.l. Os judeus jejuam <span class=\"greek\">δευτέρᾳ</span> <span class=\"greek\">σαββάτων</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πέμπτῃ</span> no segundo e no quinto dias da semana (segunda-feira e quinta-feira) D 8:1 (v. <span class=\"greek\">νηστεύω</span> e a lit. ali indicada).—ESchürer, Die siebentägige Woche im Gebr. der christl. Kirche der ersten Jahrhunderte: ZNW 6, 1905, 1–66; FColson, The Week 1926; FBoll, Hebdomas: Pauly-W. VII/2, 1912, 2547–48; RNorth, The Derivation of ‘Sabbath’, Biblica 36, ’55, 182–201; WRordorf, Sunday, trad. AGraham, ’68; BHHW III 1633–35; TRE III 608.—B. 1005. DELG s.v. <span class=\"greek\">σάββατα</span>. M-M. EDNT. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0317-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σαγήνη, ης, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σαγήνη</span>, <span class=\"greek\">ης</span>, <span class=\"greek\">ἡ</span> (Plut., Mor. 169c; Lucian, Pisc. 51, Tim. 22; Artem. 2, 14, p. 107, 13; Ael. Aristid. 13 p. 200 D.; Aelian, HA 11, 12; PTebt 868, 2 [II a.C.]; LXX; cf. o uso metaf. do verbo <span class=\"greek\">σαγηνεύω</span> Hdt. 6, 31) uma grande rede suspensa verticalmente, com flutuadores na parte superior e pesos na inferior, rede de arrasto, rede de cerco <span class=\"greek\">σαγήνῃ</span> <span class=\"greek\">βληθείσῃ</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">θάλασσαν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.47\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:47</a> (<span class=\"greek\">βάλλειν</span> <span class=\"greek\">σαγ</span>. como em Is 19:8; Babrius, Fab. 4, 1; 9, 6). V. <span class=\"greek\">ἀμφιβάλλω</span> e cf. <span class=\"greek\">ἀμφίβληστρον</span>.—DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0317-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Σαδδουκαῖος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Σαδδουκαῖος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> membro de um dos principais grupos israelitas, saduceu, sempre no pl. <span class=\"greek\">οἱ</span> <span class=\"greek\">Σαδδουκαῖοι</span> os saduceus (v. Joseph.: as passagens estão impressas em Schürer II 382f; v. pp. 384–88 quanto aos testemunhos da Mishná; cf. Billerbeck IV 339–52; Just., D. 80, 4 ao lado de outras seitas judaicas). <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:17</a> associa o sumo sacerdote e seus adeptos a esse grupo. Segundo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22:23</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:18</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.27\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 20:27</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 23:8</a>, negavam a ressurreição dos mortos. V. também <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.3.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 3:7</a>; 16:1, 6, 11f; 22:34; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:1</a>; 23:6f. Muitas questões relativas à origem, ao nome e ao caráter dos saduceus ainda não podem ser satisfatoriamente respondidas.—Wlh., Pharisäer u. die Sadd. 1874; GHölscher, Der Sadduzäismus 1906; Schürer II, 404–14; RLeszynsky, Die Sadduzäer 1912; BEerdmans, Farizeën en Saduceën: TT 48, 1914, 1–16; MSegall, Pharisees and Sadducees: Exp. 8th ser., 13, 1917, 81ff; GBox, Who Were the Sadducees in the NT: ibid. 401ff; 16, 1918, 55ff; EMeyer II 1921, 290ff; JLightley, Jewish Sects and Parties in the Time of Jesus 1923; HRasp, Fl. Joseph. u. die jüd. Religionsparteien: ZNW 23, 1924, 27–47; JJeremias, Jerusalem z. Zeit Jesu II 1924/29; Billerb. IV 1928, 334–52: D. Pharis. u. d. Sadd. in d. altjüd. Lit.; TManson, Sadducee and Pharisee—the Origin and Significance of the Names: BJRL 22, ’38, 144–59; WStrawson, Jesus and the Future Life ’59, 203–20; JLeMoyne, Les Sadducéens, ’72; ASaldarini, Pharisees, Scribes and Sadducees in Palestinian Society ’88; GStemberger, Pharisees, Sadducees, Essenes ’95; Schürer II 381f (lit.).—Kl. Pauly IV 1491f; BHHW III 1639f. EDNT. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0317-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Σαδώκ, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino indeclinável</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Σαδώκ</span>, <span class=\"greek\">ὁ</span> (<span class=\"hebrew\">צָדוֹק</span>) indecl., freq. no AT (Joseph. tem <span class=\"greek\">Σάδωκος</span>, <span class=\"greek\">ου</span> [Ant. 7, 201]; AscIs 2:5 tem <span class=\"greek\">Σαδδουκ</span>) Zadoque, na genealogia de Jesus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.1.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 1:14</a>ab; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.23\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:23</a>ff D.—M-M. BHHW III 2220.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0317-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σαίνω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σαίνω</span> (Hom. et al.)</p><p class=\"entry-text\">① prim., a respeito de cães, ‘abanar a cauda’ (Hom. et al.), daí procurar conquistar o favor mediante uma atitude destinada a granjear simpatia, adular, lisonjear (assim Trag. et al.; Antig. Car. 172 <span class=\"greek\">σαίνειν</span> <span class=\"greek\">φιλοφρόνως</span>; Jos., Bell. 6, 336). É nessa direção que muitos preferem entender o sentido da voz pass. na única passagem de nossa lit. em que a palavra ocorre, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 3:3</a> <span class=\"greek\">τὸ</span> <span class=\"greek\">μηδένα</span> <span class=\"greek\">σαίνεσθαι</span> (<span class=\"greek\">ἐν</span> <span class=\"greek\">ταῖς</span> <span class=\"greek\">θλίψεσιν</span> <span class=\"greek\">ταύταις</span>) para que ninguém seja enganado (PSchmidt, Schmiedel, Wohlenberg, GMilligan, CWilliams, Frame ad loc., também Zahn, Einl.3 I 158f). É provável que os infortúnios dos recém-convertidos oferecessem aos adversários de Paulo a oportunidade de lhes demonstrar excepcional benevolência e, assim, talvez seduzi-los a adotar as próprias opiniões desses adversários. Outros, seguindo as versões antigas e os intérpretes gregos, preferem entender <span class=\"greek\">ς</span>. no sentido de</p><p class=\"entry-text\">② fazer com que alguém fique emocionalmente abalado, comover, perturbar, agitar (Soph., Ant. 1214 <span class=\"greek\">παιδός</span> <span class=\"greek\">με</span> <span class=\"greek\">σαίνει</span> <span class=\"greek\">φθόγγος</span>; Diog. L. 8, 41 <span class=\"greek\">οἱ</span> <span class=\"greek\">σαινόμενοι</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">λεγομένοις</span> <span class=\"greek\">ἐδάκρυον</span>.—Em Stoic. III 231, 8f <span class=\"greek\">σαίνεσθαι</span> = ‘ser arrebatado por algo’), para que ninguém seja abalado ou perturbado (Bornemann, vDobschütz [p. 133f n. 3 reúne-se o material necessário à compreensão da palavra], MDibelius, Steinmann, Oepke ad loc., NRSV; HChadwick, JTS n.s. 1, ’50, 156ff). Sobre a construção v. B-D-F §399, 3; Rob. 1059; também EbNestle, ZNW 7, 1906, 361f; GMercati, ZNW 8, 1907, 242; RPerdelwitz, StKr 86, 1913, 613ff; AKnox, JTS 25, 1924, 290f; RParry, ibid. 405; IHeikel, StKr 106, ’35, 316.—DELG. M-M. TW.</p></section></article>"};
